#!/usr/bin/env node
/**
 * Tests for scripts/perimeter.ps1. Zero dependencies — `node:test` on Node 18+; needs pwsh 7 and git.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Runs the script in a throwaway repo and in a linked worktree of it: the file must land in the git
 * directory of THAT worktree, bound to its branch, UTF-8 without a BOM, readable by hooks/scope-guard.js.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, existsSync, rmSync, realpathSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'perimeter.ps1');
const hasPwsh = spawnSync('pwsh', ['-NoProfile', '-Command', '$PSVersionTable.PSVersion.Major'], { encoding: 'utf8' }).status === 0;
const skip = hasPwsh ? false : 'pwsh 7 not on PATH';

const git = (cwd, ...args) => {
  const r = spawnSync('git', ['-c', 'user.email=t@t', '-c', 'user.name=t', ...args], { cwd, encoding: 'utf8' });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout.trim();
};
const perimeter = (cwd, ...args) => spawnSync('pwsh', ['-NoProfile', '-File', SCRIPT, ...args], { cwd, encoding: 'utf8' });

const sandbox = realpathSync(mkdtempSync(join(tmpdir(), 'perim-')));
process.on('exit', () => { try { rmSync(sandbox, { recursive: true, force: true }); } catch { /* tmp */ } });

test('writes the perimeter in the git dir, bound to the branch; -Close keeps the entries and closes it', { skip }, () => {
  const repo = join(sandbox, 'main');
  git(sandbox, 'init', '-b', 'trunk', repo);
  git(repo, 'commit', '--allow-empty', '-m', 'init');
  const r = perimeter(repo, '-Files', 'src/a.cs,src/Dto/, tests/**/A*.cs');
  assert.equal(r.status, 0, r.stderr);
  const file = join(repo, '.git', 'deliver', 'perimeter.md');
  const bytes = readFileSync(file);
  assert.notDeepEqual([...bytes.subarray(0, 3)], [0xef, 0xbb, 0xbf]);          // no BOM
  assert.equal(bytes.toString('utf8'), 'branch: trunk\nstatus: active\n- src/a.cs\n- src/Dto/\n- tests/**/A*.cs\n');
  assert.equal(perimeter(repo, '-Close').status, 0);
  assert.equal(readFileSync(file, 'utf8'), 'branch: trunk\nstatus: closed\n- src/a.cs\n- src/Dto/\n- tests/**/A*.cs\n');
  // a new triage overwrites it
  perimeter(repo, '-Files', 'only.cs');
  assert.equal(readFileSync(file, 'utf8'), 'branch: trunk\nstatus: active\n- only.cs\n');
});

test('in a linked worktree the file goes to that worktree\'s git dir, with its own branch', { skip }, () => {
  const repo = join(sandbox, 'main2');
  git(sandbox, 'init', '-b', 'trunk', repo);
  git(repo, 'commit', '--allow-empty', '-m', 'init');
  const wt = join(sandbox, 'wt');
  git(repo, 'worktree', 'add', '-b', 'feat/x', wt);
  const r = perimeter(wt, '-Files', 'src/a.cs');
  assert.equal(r.status, 0, r.stderr);
  const gitDir = git(wt, 'rev-parse', '--absolute-git-dir');
  assert.equal(readFileSync(join(gitDir, 'deliver', 'perimeter.md'), 'utf8'), 'branch: feat/x\nstatus: active\n- src/a.cs\n');
  assert.ok(!existsSync(join(repo, '.git', 'deliver', 'perimeter.md')));
});

test('usage errors exit 2: no entries, outside a repository, detached HEAD, nothing to close', { skip }, () => {
  const repo = join(sandbox, 'main3');
  git(sandbox, 'init', '-b', 'trunk', repo);
  git(repo, 'commit', '--allow-empty', '-m', 'init');
  assert.equal(perimeter(repo).status, 2);
  assert.equal(perimeter(repo, '-Close').status, 2);
  assert.equal(perimeter(join(sandbox), '-Files', 'a.cs').status, 2);
  git(repo, 'checkout', '--detach');
  assert.equal(perimeter(repo, '-Files', 'a.cs').status, 2);
});
